import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
# Structural rewrite: CTA-level output/spatial tiling with shared-memory staging.
# Specialized for the provided ConvTranspose3d shape: stride=1, padding=0,
# output_padding=0, groups=1, kernel=(3,5,7). Each CTA computes one output tile
# of 16 output channels x TD=1 x TH=8 x TW=24 using per-thread 4x output-channel x 4x spatial-W register blocking and a shared-memory input halo.
PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
.extern .shared .align 4 .b8 smem[];
.visible .entry conv_transpose3d_fwd(
    .param .u64 p_in,
    .param .u64 p_wt,
    .param .u64 p_bias,
    .param .u64 p_out,
    .param .u32 p_total,
    .param .u32 p_has_bias,
    .param .u32 p_IC,
    .param .u32 p_OC,
    .param .u32 p_OCpG,
    .param .u32 p_ICpG,
    .param .u32 p_Din,
    .param .u32 p_Hin,
    .param .u32 p_Win,
    .param .u32 p_Dout,
    .param .u32 p_Hout,
    .param .u32 p_Wout,
    .param .u32 p_KD,
    .param .u32 p_KH,
    .param .u32 p_KW,
    .param .u32 p_SD,
    .param .u32 p_SH,
    .param .u32 p_SW,
    .param .u32 p_PD,
    .param .u32 p_PH,
    .param .u32 p_PW
) .maxnreg 52
{
    .reg .b64 %rd_in, %rd_wt, %rd_bias, %rd_out, %rd_a, %rd_b;
    .reg .b32 %r_smem, %r_sa, %r_sb;
    .reg .b32 %r_bid, %r_tid, %r_has_bias;
    .reg .b32 %r_IC, %r_OC, %r_Din, %r_Hin, %r_Win, %r_Dout, %r_Hout, %r_Wout;
    .reg .b32 %r_WT, %r_HT, %r_wt, %r_ht, %r_q, %r_t0, %r_t1, %r_t2;
    .reg .b32 %r_b, %r_oc, %r_oct, %r_oc1, %r_oc2, %r_oc3, %r_d, %r_h0, %r_w0, %r_hl, %r_wl, %r_h, %r_w;
    .reg .b32 %r_HWin, %r_DHWin, %r_inb, %r_chunk, %r_nchunk, %r_OCT, %r_plane;
    .reg .b32 %r_idx, %r_ic, %r_di, %r_hh, %r_ww, %r_rem, %r_sidx;
    .reg .b32 %r_gdi, %r_ghh, %r_gww, %r_icg, %r_iaddr, %r_waddr, %r_koff;
    .reg .b32 %r_kd, %r_kh, %r_kw, %r_sdi, %r_shh, %r_sww;
    .reg .b32 %r_oaddr, %r_og, %r_lane;
    .reg .pred %p0, %p1, %p2, %pv0, %pv1, %pv2, %pv3, %p_oc0, %p_oc1, %p_oc2, %p_oc3;
    .reg .f32 %f_a0, %f_a1, %f_a2, %f_a3, %f_a4, %f_a5, %f_a6, %f_a7;
    .reg .f32 %f_a8, %f_a9, %f_a10, %f_a11, %f_a12, %f_a13, %f_a14, %f_a15;
    .reg .f32 %f_v, %f_v2, %f_v3, %f_v4, %f_w, %f_w1, %f_w2, %f_w3;
    ld.param.u64 %rd_in, [p_in];
    ld.param.u64 %rd_wt, [p_wt];
    ld.param.u64 %rd_bias, [p_bias];
    ld.param.u64 %rd_out, [p_out];
    ld.param.u32 %r_has_bias, [p_has_bias];
    ld.param.u32 %r_IC, [p_IC];
    ld.param.u32 %r_OC, [p_OC];
    ld.param.u32 %r_Din, [p_Din];
    ld.param.u32 %r_Hin, [p_Hin];
    ld.param.u32 %r_Win, [p_Win];
    ld.param.u32 %r_Dout, [p_Dout];
    ld.param.u32 %r_Hout, [p_Hout];
    ld.param.u32 %r_Wout, [p_Wout];
    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_bid, %ctaid.x;
    mov.u32 %r_smem, smem;
    mov.f32 %f_a0, 0f00000000;
    mov.f32 %f_a1, 0f00000000;
    mov.f32 %f_a2, 0f00000000;
    mov.f32 %f_a3, 0f00000000;
    mov.f32 %f_a4, 0f00000000;
    mov.f32 %f_a5, 0f00000000;
    mov.f32 %f_a6, 0f00000000;
    mov.f32 %f_a7, 0f00000000;
    mov.f32 %f_a8, 0f00000000;
    mov.f32 %f_a9, 0f00000000;
    mov.f32 %f_a10, 0f00000000;
    mov.f32 %f_a11, 0f00000000;
    mov.f32 %f_a12, 0f00000000;
    mov.f32 %f_a13, 0f00000000;
    mov.f32 %f_a14, 0f00000000;
    mov.f32 %f_a15, 0f00000000;
    // WT = ceil(Wout/24), HT = ceil(Hout/8), OCT = ceil(OC/16)
    add.u32 %r_WT, %r_Wout, 23;
    div.u32 %r_WT, %r_WT, 24;
    add.u32 %r_HT, %r_Hout, 7;
    shr.u32 %r_HT, %r_HT, 3;
    add.u32 %r_OCT, %r_OC, 15;
    shr.u32 %r_OCT, %r_OCT, 4;
    // decode bid -> (b, oc_group, d, ht, wt)
    div.u32 %r_q, %r_bid, %r_WT;
    mul.lo.u32 %r_t0, %r_q, %r_WT;
    sub.u32 %r_wt, %r_bid, %r_t0;
    div.u32 %r_t0, %r_q, %r_HT;
    mul.lo.u32 %r_t1, %r_t0, %r_HT;
    sub.u32 %r_ht, %r_q, %r_t1;
    div.u32 %r_t1, %r_t0, %r_Dout;
    mul.lo.u32 %r_t2, %r_t1, %r_Dout;
    sub.u32 %r_d, %r_t0, %r_t2;
    div.u32 %r_t0, %r_t1, %r_OCT;
    mul.lo.u32 %r_t2, %r_t0, %r_OCT;
    sub.u32 %r_oct, %r_t1, %r_t2;
    mov.u32 %r_b, %r_t0;
    // Four 48-thread groups each compute a quad of output channels; each thread also computes four adjacent W outputs (16 accumulators), doubling weight-load reuse.
    div.u32 %r_og, %r_tid, 48;
    rem.u32 %r_lane, %r_tid, 48;
    shl.b32 %r_oc, %r_oct, 4;
    shl.b32 %r_t0, %r_og, 2;
    add.u32 %r_oc, %r_oc, %r_t0;
    add.u32 %r_oc1, %r_oc, 1;
    add.u32 %r_oc2, %r_oc, 2;
    add.u32 %r_oc3, %r_oc, 3;
    setp.lt.u32 %p_oc0, %r_oc, %r_OC;
    setp.lt.u32 %p_oc1, %r_oc1, %r_OC;
    setp.lt.u32 %p_oc2, %r_oc2, %r_OC;
    setp.lt.u32 %p_oc3, %r_oc3, %r_OC;
    shl.b32 %r_h0, %r_ht, 3;
    mul.lo.u32 %r_w0, %r_wt, 24;
    div.u32 %r_hl, %r_lane, 6;      // lane / 6
    rem.u32 %r_wl, %r_lane, 6;      // lane % 6
    shl.b32 %r_wl, %r_wl, 2;         // each thread covers W quad (4*wlp .. 4*wlp+3)
    add.u32 %r_h, %r_h0, %r_hl;
    add.u32 %r_w, %r_w0, %r_wl;
    setp.lt.u32 %p0, %r_h, %r_Hout;
    setp.lt.u32 %p1, %r_w, %r_Wout;
    and.pred %pv0, %p0, %p1;
    add.u32 %r_t0, %r_w, 1;
    setp.lt.u32 %p1, %r_t0, %r_Wout;
    and.pred %pv1, %p0, %p1;
    add.u32 %r_t0, %r_w, 2;
    setp.lt.u32 %p1, %r_t0, %r_Wout;
    and.pred %pv2, %p0, %p1;
    add.u32 %r_t0, %r_w, 3;
    setp.lt.u32 %p1, %r_t0, %r_Wout;
    and.pred %pv3, %p0, %p1;
    mul.lo.u32 %r_HWin, %r_Hin, %r_Win;
    mul.lo.u32 %r_DHWin, %r_Din, %r_HWin;
    mul.lo.u32 %r_t0, %r_b, %r_IC;
    mul.lo.u32 %r_inb, %r_t0, %r_DHWin;
    mul.lo.u32 %r_plane, %r_Dout, %r_Hout;
    mul.lo.u32 %r_plane, %r_plane, %r_Wout;
    shr.u32 %r_nchunk, %r_IC, 2;     // IC / 4, exact for provided shape
    mov.u32 %r_chunk, 0;
L_CHUNK:
    // Cooperatively stage shared input halo: [ic4][di3][hh12][ww30] floats.
    mov.u32 %r_idx, %r_tid;
L_STAGE:
    setp.lt.u32 %p0, %r_idx, 4320;
    @!%p0 bra L_STAGE_DONE;
    div.u32 %r_ic, %r_idx, 1080;
    mul.lo.u32 %r_t0, %r_ic, 1080;
    sub.u32 %r_rem, %r_idx, %r_t0;
    div.u32 %r_di, %r_rem, 360;
    mul.lo.u32 %r_t0, %r_di, 360;
    sub.u32 %r_rem, %r_rem, %r_t0;
    div.u32 %r_hh, %r_rem, 30;
    mul.lo.u32 %r_t0, %r_hh, 30;
    sub.u32 %r_ww, %r_rem, %r_t0;
    // global input coords with halo origins d-2, h0-4, w0-6
    add.s32 %r_gdi, %r_d, -2;
    add.s32 %r_gdi, %r_gdi, %r_di;
    add.s32 %r_ghh, %r_h0, -4;
    add.s32 %r_ghh, %r_ghh, %r_hh;
    add.s32 %r_gww, %r_w0, -6;
    add.s32 %r_gww, %r_gww, %r_ww;
    shl.b32 %r_t0, %r_chunk, 2;
    add.u32 %r_icg, %r_t0, %r_ic;
    setp.ge.s32 %p0, %r_gdi, 0;
    setp.lt.s32 %p1, %r_gdi, %r_Din;
    and.pred %p0, %p0, %p1;
    setp.ge.s32 %p1, %r_ghh, 0;
    and.pred %p0, %p0, %p1;
    setp.lt.s32 %p1, %r_ghh, %r_Hin;
    and.pred %p0, %p0, %p1;
    setp.ge.s32 %p1, %r_gww, 0;
    and.pred %p0, %p0, %p1;
    setp.lt.s32 %p1, %r_gww, %r_Win;
    and.pred %p0, %p0, %p1;
    mov.f32 %f_v, 0f00000000;
    mul.lo.u32 %r_t0, %r_icg, %r_DHWin;
    add.u32 %r_t0, %r_t0, %r_inb;
    mul.lo.u32 %r_t1, %r_gdi, %r_HWin;
    add.u32 %r_t0, %r_t0, %r_t1;
    mul.lo.u32 %r_t1, %r_ghh, %r_Win;
    add.u32 %r_t0, %r_t0, %r_t1;
    add.u32 %r_iaddr, %r_t0, %r_gww;
    mul.wide.u32 %rd_a, %r_iaddr, 4;
    add.u64 %rd_a, %rd_a, %rd_in;
    @%p0 ld.global.nc.f32 %f_v, [%rd_a];
    mul.lo.u32 %r_t0, %r_ic, 3;
    add.u32 %r_t0, %r_t0, %r_di;
    mul.lo.u32 %r_t0, %r_t0, 12;
    add.u32 %r_t0, %r_t0, %r_hh;
    mul.lo.u32 %r_sidx, %r_t0, 30;
    add.u32 %r_sidx, %r_sidx, %r_ww;
    shl.b32 %r_sb, %r_sidx, 2;
    add.u32 %r_sb, %r_sb, %r_smem;
    st.shared.f32 [%r_sb], %f_v;
    add.u32 %r_idx, %r_idx, 192;
    bra L_STAGE;
L_STAGE_DONE:
    bar.sync 0;
    // Compute this CTA tile from staged input. Shift the overlapping four-value W halo through registers across KW so each subsequent KW step requires only one new shared-memory load.
    mov.u32 %r_kd, 0;
L_KD:
    mov.u32 %r_kh, 0;
L_KH:
    // Shared local coordinates at KW=0: di=2-kd, hh=hl+4-kh, ww=wl+6.
    mov.u32 %r_sdi, 2;
    sub.u32 %r_sdi, %r_sdi, %r_kd;
    add.u32 %r_shh, %r_hl, 4;
    sub.u32 %r_shh, %r_shh, %r_kh;
    add.u32 %r_sww, %r_wl, 6;
    mul.lo.u32 %r_t0, %r_kd, 5;
    add.u32 %r_t0, %r_t0, %r_kh;
    mul.lo.u32 %r_koff, %r_t0, 7;
    mov.u32 %r_ic, 0;
L_IC4:
    shl.b32 %r_t0, %r_chunk, 2;
    add.u32 %r_icg, %r_t0, %r_ic;
    mul.lo.u32 %r_t0, %r_ic, 3;
    add.u32 %r_t0, %r_t0, %r_sdi;
    mul.lo.u32 %r_t0, %r_t0, 12;
    add.u32 %r_t0, %r_t0, %r_shh;
    mul.lo.u32 %r_sidx, %r_t0, 30;
    add.u32 %r_sidx, %r_sidx, %r_sww;
    shl.b32 %r_sa, %r_sidx, 2;
    add.u32 %r_sa, %r_sa, %r_smem;
    ld.shared.f32 %f_v, [%r_sa];
    ld.shared.f32 %f_v2, [%r_sa + 4];
    ld.shared.f32 %f_v3, [%r_sa + 8];
    ld.shared.f32 %f_v4, [%r_sa + 12];
    mul.lo.u32 %r_t1, %r_icg, %r_OC;
    add.u32 %r_t1, %r_t1, %r_oc;
    mul.lo.u32 %r_waddr, %r_t1, 105;
    add.u32 %r_waddr, %r_waddr, %r_koff;
    mul.wide.u32 %rd_b, %r_waddr, 4;
    add.u64 %rd_b, %rd_b, %rd_wt;
    mov.u32 %r_kw, 0;
L_KW:
    @%p_oc0 ld.global.nc.f32 %f_w, [%rd_b];
    @%p_oc0 fma.rn.f32 %f_a0, %f_v, %f_w, %f_a0;
    @%p_oc0 fma.rn.f32 %f_a4, %f_v2, %f_w, %f_a4;
    @%p_oc0 fma.rn.f32 %f_a8, %f_v3, %f_w, %f_a8;
    @%p_oc0 fma.rn.f32 %f_a12, %f_v4, %f_w, %f_a12;
    @%p_oc1 ld.global.nc.f32 %f_w1, [%rd_b + 420];
    @%p_oc1 fma.rn.f32 %f_a1, %f_v, %f_w1, %f_a1;
    @%p_oc1 fma.rn.f32 %f_a5, %f_v2, %f_w1, %f_a5;
    @%p_oc1 fma.rn.f32 %f_a9, %f_v3, %f_w1, %f_a9;
    @%p_oc1 fma.rn.f32 %f_a13, %f_v4, %f_w1, %f_a13;
    @%p_oc2 ld.global.nc.f32 %f_w2, [%rd_b + 840];
    @%p_oc2 fma.rn.f32 %f_a2, %f_v, %f_w2, %f_a2;
    @%p_oc2 fma.rn.f32 %f_a6, %f_v2, %f_w2, %f_a6;
    @%p_oc2 fma.rn.f32 %f_a10, %f_v3, %f_w2, %f_a10;
    @%p_oc2 fma.rn.f32 %f_a14, %f_v4, %f_w2, %f_a14;
    @%p_oc3 ld.global.nc.f32 %f_w3, [%rd_b + 1260];
    @%p_oc3 fma.rn.f32 %f_a3, %f_v, %f_w3, %f_a3;
    @%p_oc3 fma.rn.f32 %f_a7, %f_v2, %f_w3, %f_a7;
    @%p_oc3 fma.rn.f32 %f_a11, %f_v3, %f_w3, %f_a11;
    @%p_oc3 fma.rn.f32 %f_a15, %f_v4, %f_w3, %f_a15;
    add.u32 %r_kw, %r_kw, 1;
    setp.lt.u32 %p0, %r_kw, 7;
    @!%p0 bra L_KW_DONE;
    // Advance to the next KW by reusing three values and loading only the new left edge.
    mov.f32 %f_v4, %f_v3;
    mov.f32 %f_v3, %f_v2;
    mov.f32 %f_v2, %f_v;
    sub.u32 %r_sa, %r_sa, 4;
    ld.shared.f32 %f_v, [%r_sa];
    add.u64 %rd_b, %rd_b, 4;
    bra L_KW;
L_KW_DONE:
    add.u32 %r_ic, %r_ic, 1;
    setp.lt.u32 %p0, %r_ic, 4;
    @%p0 bra L_IC4;
    add.u32 %r_kh, %r_kh, 1;
    setp.lt.u32 %p0, %r_kh, 5;
    @%p0 bra L_KH;
    add.u32 %r_kd, %r_kd, 1;
    setp.lt.u32 %p0, %r_kd, 3;
    @%p0 bra L_KD;
    bar.sync 0;
    add.u32 %r_chunk, %r_chunk, 1;
    setp.lt.u32 %p0, %r_chunk, %r_nchunk;
    @%p0 bra L_CHUNK;
    setp.eq.u32 %p0, %r_has_bias, 0;
    @%p0 bra L_STORE;
    @!%p_oc0 bra L_BIAS_OC1;
    mul.wide.u32 %rd_a, %r_oc, 4;
    add.u64 %rd_a, %rd_a, %rd_bias;
    ld.global.nc.f32 %f_v, [%rd_a];
    add.f32 %f_a0, %f_a0, %f_v;
    add.f32 %f_a4, %f_a4, %f_v;
    add.f32 %f_a8, %f_a8, %f_v;
    add.f32 %f_a12, %f_a12, %f_v;
L_BIAS_OC1:
    @!%p_oc1 bra L_BIAS_OC2;
    ld.global.nc.f32 %f_v, [%rd_a + 4];
    add.f32 %f_a1, %f_a1, %f_v;
    add.f32 %f_a5, %f_a5, %f_v;
    add.f32 %f_a9, %f_a9, %f_v;
    add.f32 %f_a13, %f_a13, %f_v;
L_BIAS_OC2:
    @!%p_oc2 bra L_BIAS_OC3;
    ld.global.nc.f32 %f_v, [%rd_a + 8];
    add.f32 %f_a2, %f_a2, %f_v;
    add.f32 %f_a6, %f_a6, %f_v;
    add.f32 %f_a10, %f_a10, %f_v;
    add.f32 %f_a14, %f_a14, %f_v;
L_BIAS_OC3:
    @!%p_oc3 bra L_STORE;
    ld.global.nc.f32 %f_v, [%rd_a + 12];
    add.f32 %f_a3, %f_a3, %f_v;
    add.f32 %f_a7, %f_a7, %f_v;
    add.f32 %f_a11, %f_a11, %f_v;
    add.f32 %f_a15, %f_a15, %f_v;
L_STORE:
    mul.lo.u32 %r_t0, %r_b, %r_OC;
    add.u32 %r_t0, %r_t0, %r_oc;
    mul.lo.u32 %r_t0, %r_t0, %r_Dout;
    add.u32 %r_t0, %r_t0, %r_d;
    mul.lo.u32 %r_t0, %r_t0, %r_Hout;
    add.u32 %r_t0, %r_t0, %r_h;
    mul.lo.u32 %r_oaddr, %r_t0, %r_Wout;
    add.u32 %r_oaddr, %r_oaddr, %r_w;
    // oc0: store all four W outputs (at +0, +1, +2, +3 elements)
    mul.wide.u32 %rd_a, %r_oaddr, 4;
    add.u64 %rd_a, %rd_a, %rd_out;
    and.pred %p2, %pv0, %p_oc0;
    @%p2 st.global.f32 [%rd_a], %f_a0;
    and.pred %p2, %pv1, %p_oc0;
    @%p2 st.global.f32 [%rd_a + 4], %f_a4;
    and.pred %p2, %pv2, %p_oc0;
    @%p2 st.global.f32 [%rd_a + 8], %f_a8;
    and.pred %p2, %pv3, %p_oc0;
    @%p2 st.global.f32 [%rd_a + 12], %f_a12;
    // oc1
    add.u32 %r_oaddr, %r_oaddr, %r_plane;
    mul.wide.u32 %rd_a, %r_oaddr, 4;
    add.u64 %rd_a, %rd_a, %rd_out;
    and.pred %p2, %pv0, %p_oc1;
    @%p2 st.global.f32 [%rd_a], %f_a1;
    and.pred %p2, %pv1, %p_oc1;
    @%p2 st.global.f32 [%rd_a + 4], %f_a5;
    and.pred %p2, %pv2, %p_oc1;
    @%p2 st.global.f32 [%rd_a + 8], %f_a9;
    and.pred %p2, %pv3, %p_oc1;
    @%p2 st.global.f32 [%rd_a + 12], %f_a13;
    // oc2
    add.u32 %r_oaddr, %r_oaddr, %r_plane;
    mul.wide.u32 %rd_a, %r_oaddr, 4;
    add.u64 %rd_a, %rd_a, %rd_out;
    and.pred %p2, %pv0, %p_oc2;
    @%p2 st.global.f32 [%rd_a], %f_a2;
    and.pred %p2, %pv1, %p_oc2;
    @%p2 st.global.f32 [%rd_a + 4], %f_a6;
    and.pred %p2, %pv2, %p_oc2;
    @%p2 st.global.f32 [%rd_a + 8], %f_a10;
    and.pred %p2, %pv3, %p_oc2;
    @%p2 st.global.f32 [%rd_a + 12], %f_a14;
    // oc3
    add.u32 %r_oaddr, %r_oaddr, %r_plane;
    mul.wide.u32 %rd_a, %r_oaddr, 4;
